{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 1,
      "verse": 11,
      "text_ar": "وتعدى آدم وامرأته وصية الله التي أوصاهما بها، وعلم الله ذلك، فحمي غضبه عليهما ولعنهما."
    },
    {
      "chapter": 1,
      "verse": 12,
      "text_ar": "وطردهما الرب الإله في ذلك اليوم من جنة عدن ليعملا الأرض التي أخذا منها، فذهبا وسكنا شرقي جنة عدن؛ وعارف آدم حواء امرأته فولدت ابنين وثلاث بنات."
    },
    {
      "chapter": 1,
      "verse": 13,
      "text_ar": "ودعت اسم البكر قايين، قائلةً: \"قد اقتنيتُ رجلاً من عند الرب\"، ودعت اسم الآخر هابيل، لأنها قالت: \"بالباطل أتينا إلى الأرض، وبالباطل نُؤخذ منها\"."
    },
    {
      "chapter": 1,
      "verse": 14,
      "text_ar": "وكبر الولدان فأعطاهما أبوهما ملكاً في الأرض؛ وكان قايين عامل أرض، وهابيل راعي غنم."
    },
    {
      "chapter": 1,
      "verse": 15,
      "text_ar": "وكان في نهاية سنين، أنهما قدما قرباناً تقريبياً للرب، فأقدم قايين من ثمر الأرض، وأقدم هابيل من أبكار غنمه ومن سمانها، فالتفت الرب ورضي على هابيل وقربانه، ونزلت نار من عند الرب من السماء فأكلته."
    },
    {
      "chapter": 1,
      "verse": 16,
      "text_ar": "وأما قايين وقربانه فلم يلتفت إليهما الرب ولم يرضَ عنهما، لأنه كان قد قدم من رديء ثمر الأرض أمام الرب، فغار قايين على أخيه هابيل بسبب ذلك، والتمس حجة لقتله."
    },
    {
      "chapter": 1,
      "verse": 17,
      "text_ar": "وفي وقت بعد ذلك، ذهب قايين وهابيل أخوه ذات يوم إلى الحقل ليقوما بعملهما؛ وكانا كلاهما في الحقل، قايين يفلح ويحرث أرضه، وهابيل يرعى غنمه؛ فمرت الغنم بذلك الجزء الذي حرثه قايين في الأرض، فأحزن ذلك قايين جداً بسبب هذا."
    },
    {
      "chapter": 1,
      "verse": 18,
      "text_ar": "واقترب قايين من أخيه هابيل بغضب، وقال له: \"ما بيني وبينك حتى جئت تسكن وتأتي بغنمك لترعى في أرضي؟\""
    },
    {
      "chapter": 1,
      "verse": 19,
      "text_ar": "فأجاب هابيل أخاه قايين وقال له: \"ما بيني وبينك حتى تأكل لحم غنمي وتكتسي بصوفها؟\""
    },
    {
      "chapter": 1,
      "verse": 20,
      "text_ar": "والآن لذلك، انزع صوف غنمي الذي اكتسيتَ به، وعوضني عن ثمرها ولحمها الذي أكلته، ومتى فعلت هذا، فحينئذ أذهب عن أرضك كما قلتَ."
    }
  ]
}
